<script setup lang="ts">
import{onMounted,ref}from'vue';import{api}from'../api';import{ElMessage}from'element-plus'
const courses=ref<any[]>([]),classes=ref<any[]>([]),courseId=ref(''),classId=ref(''),overview=ref<any>(null),loading=ref(false)
async function loadCourses(){courses.value=(await api.get('/teacher/courses')).data;if(!courseId.value&&courses.value.length)courseId.value=courses.value[0].course_id;await courseChanged()}
async function courseChanged(){classId.value='';classes.value=(await api.get('/teacher/classes',{params:{course_id:courseId.value}})).data;await loadOverview()}
async function loadOverview(){if(!courseId.value)return;loading.value=true;try{overview.value=(await api.get(`/teacher/courses/${courseId.value}/teaching-overview`,{params:classId.value?{class_id:classId.value}:{}})).data}catch(e:any){ElMessage.error(e.response?.data?.detail||'教学诊断加载失败')}finally{loading.value=false}}
const severity=(value:string)=>value==='high'?'danger':value==='medium'?'warning':'info'
onMounted(loadCourses)
</script>
<template><main class="content teaching-overview" v-loading="loading"><div class="page-title"><span class="eyebrow">TEACHING INSIGHTS</span><h1>教学诊断</h1><p class="muted">把知识建设、学生提问和练习结果转化为教师可以立即处理的事项。</p></div><el-card shadow="never" class="overview-filter"><el-row :gutter="14"><el-col :span="10"><el-select v-model="courseId" @change="courseChanged"><el-option v-for="x in courses" :key="x.course_id" :label="x.course_name" :value="x.course_id"/></el-select></el-col><el-col :span="10"><el-select v-model="classId" clearable placeholder="全部教学班（课程匿名聚合）" @change="loadOverview"><el-option v-for="x in classes" :key="x.class_id" :label="`${x.class_name} · ${x.term_name}`" :value="x.class_id"/></el-select></el-col><el-col :span="4"><el-button @click="loadOverview">刷新</el-button></el-col></el-row></el-card><template v-if="overview"><el-alert v-if="overview.data_scope==='course_only'" type="warning" :closable="false" :title="overview.scope_note"/><section class="metric-grid six"><el-card shadow="never"><span>资料</span><b>{{overview.knowledge.readiness.document_count}}</b></el-card><el-card shadow="never"><span>已批准知识点</span><b>{{overview.knowledge.readiness.approved_knowledge_points}}</b></el-card><el-card shadow="never"><span>待处理阻塞</span><b>{{overview.knowledge.readiness.blockers.length}}</b></el-card><el-card shadow="never"><span>活跃学生</span><b>{{overview.learning.active_students}}</b></el-card><el-card shadow="never"><span>提问</span><b>{{overview.learning.question_count}}</b></el-card><el-card shadow="never"><span>练习</span><b>{{overview.learning.quiz_count}}</b></el-card></section><el-row :gutter="18"><el-col :span="14"><el-card shadow="never"><template #header><b>优先处理</b></template><el-empty v-if="!overview.priorities.length" description="暂无需要优先处理的问题"/><el-table v-else :data="overview.priorities"><el-table-column label="等级" width="90"><template #default="s"><el-tag :type="severity(s.row.severity)">{{s.row.severity}}</el-tag></template></el-table-column><el-table-column prop="title" label="现象" min-width="220"/><el-table-column prop="evidence_count" label="证据数" width="90"/><el-table-column label="操作" width="100"><template #default="s"><el-button link type="primary" @click="$router.push(s.row.target)">处理</el-button></template></el-table-column></el-table></el-card></el-col><el-col :span="10"><el-card shadow="never"><template #header><b>知识库发布准备度</b></template><el-result :icon="overview.knowledge.readiness.can_publish?'success':'warning'" :title="overview.knowledge.readiness.can_publish?'可以发布':'暂不可发布'" :sub-title="`当前版本 v${overview.knowledge.readiness.publication.version_number}`"/><div v-for="x in overview.knowledge.readiness.blockers" :key="x.code" class="diagnostic-item">{{x.message}} <el-tag>{{x.count}}</el-tag></div></el-card></el-col></el-row><el-row :gutter="18" class="diagnostic-row"><el-col :span="12"><el-card shadow="never"><template #header><b>薄弱知识点</b></template><el-table :data="overview.learning.weak_points"><el-table-column prop="knowledge_point" label="知识点"/><el-table-column prop="answered" label="作答" width="75"/><el-table-column prop="accuracy" label="正确率" width="90"><template #default="s">{{s.row.accuracy}}%</template></el-table-column></el-table></el-card></el-col><el-col :span="12"><el-card shadow="never"><template #header><b>资料未覆盖问题</b></template><el-table :data="overview.learning.uncovered_questions"><el-table-column prop="question" label="问题"/><el-table-column prop="count" label="次数" width="75"/></el-table></el-card></el-col></el-row></template></main></template>
